/* GTK3: push / normal
 * Paleta: papéis KDE; amostra da pipeta não aplicada.
 * Herda de * no tema gerado: font-size: 13px.
 * Máscaras adaptive/ são emitidas somente por --generate. */
button, .button { min-width: 16px; min-height: 18px; padding: 4px 6px; border: 2px solid; }
button, .button {
  color: @theme_button_foreground_normal_breeze;
  background-color: @theme_button_background_normal_breeze;
  border-color: mix(@theme_button_background_normal_breeze, #ffffff, 0.56) mix(@theme_button_background_normal_breeze, #000000, 0.482) mix(@theme_button_background_normal_breeze, #000000, 0.482) mix(@theme_button_background_normal_breeze, #ffffff, 0.56);
  outline-color: @theme_button_decoration_focus_breeze;
}
button.flat {
  color: @theme_button_foreground_normal_breeze;
  background-color: @theme_button_background_normal_breeze;
  border-color: transparent;
  outline-color: @theme_button_decoration_focus_breeze;
}
button.default {
  box-shadow: 0 0 0 2px @theme_titlebar_background_breeze;
}
button, .button {
  padding: 4px;
}

